#!/bin/sh
# Generated by forge. UserPromptSubmit: snapshots the working tree at the start
# of the turn (.forge/state/<session>.turn/), so the Stop hook checks only what
# changed during the turn, and resets the Stop block counter. Prints nothing
# (its output would reach Claude).
dir=$(cd "$(dirname "$0")" && pwd)
FORGE_INPUT=$(cat)
. "$dir/lib.sh"
repo_root || exit 0
mkdir -p .forge/state 2>/dev/null || exit 0
snapshot "$(turn_dir)" 2>/dev/null
rm -f ".forge/state/$(session_id).blocks"
exit 0
